INSERT INTO homologies (id, source_id, target_id, status, confidence, method, source_dataset_id, created_at) VALUES
  ('homology.human_macaque.motor_sma_synthesis.l_6ma_sma', 'region.human.hcp-mmp1.l_6ma', 'region.macaque.wang2017.l_sma', 'uncertain_correspondence', NULL, 'sintesis de NeuroGraph combinando cuatro fuentes reales, ninguna de las cuales declara por si sola esta correspondencia completa (nunca candidate_homology, reservado para una tabla region-a-region de un unico estudio, como Cheng et al. 2021): (1) Glasser et al. 2016 (Nature, DOI 10.1038/nature18933) agrupa 6ma/6mp/SCEF como ''areas motoras suplementarias'' sin distinguir SMA-proper de pre-SMA dentro del grupo; (2) Luppino, Matelli, Camarda y Rizzolatti (1993, J Comp Neurol, PMID 7507940) definen en macaco area F3=SMA-proper y F6=pre-SMA, linaje citoarquitectonico del que deriva la etiqueta SMA de Wang et al. 2017 (cita a Barbas y Pandya 1987); (3) Zilles et al. (1995, J Anat 187:515-537, PMID 8586553) establecen correspondencia multimodal humano-macaco para SMA/areas motoras cingulares; (4) Mars et al. (2018, eLife, DOI 10.7554/eLife.35237) validan cuantitativamente (conectividad) que la pre-SMA humana corresponde al area F6 del macaco. Wang et al. 2017 no tiene cargada ninguna region F6/pre-SMA de macaco todavia, asi que la correspondencia se enlaza solo con su SMA. Aviso aparte: SCEF (''supplementary and cingulate eye field'') es, por su propio nombre, un area oculomotora, no de movimiento de extremidades -- se incluye solo porque el propio Glasser et al. 2016 la agrupa junto a 6ma/6mp, sin evidencia propia verificada de participacion en circuitos procedimentales de extremidades.', NULL, now()),
  ('homology.human_macaque.motor_sma_synthesis.l_6mp_sma', 'region.human.hcp-mmp1.l_6mp', 'region.macaque.wang2017.l_sma', 'uncertain_correspondence', NULL, 'sintesis de NeuroGraph combinando cuatro fuentes reales, ninguna de las cuales declara por si sola esta correspondencia completa (nunca candidate_homology, reservado para una tabla region-a-region de un unico estudio, como Cheng et al. 2021): (1) Glasser et al. 2016 (Nature, DOI 10.1038/nature18933) agrupa 6ma/6mp/SCEF como ''areas motoras suplementarias'' sin distinguir SMA-proper de pre-SMA dentro del grupo; (2) Luppino, Matelli, Camarda y Rizzolatti (1993, J Comp Neurol, PMID 7507940) definen en macaco area F3=SMA-proper y F6=pre-SMA, linaje citoarquitectonico del que deriva la etiqueta SMA de Wang et al. 2017 (cita a Barbas y Pandya 1987); (3) Zilles et al. (1995, J Anat 187:515-537, PMID 8586553) establecen correspondencia multimodal humano-macaco para SMA/areas motoras cingulares; (4) Mars et al. (2018, eLife, DOI 10.7554/eLife.35237) validan cuantitativamente (conectividad) que la pre-SMA humana corresponde al area F6 del macaco. Wang et al. 2017 no tiene cargada ninguna region F6/pre-SMA de macaco todavia, asi que la correspondencia se enlaza solo con su SMA. Aviso aparte: SCEF (''supplementary and cingulate eye field'') es, por su propio nombre, un area oculomotora, no de movimiento de extremidades -- se incluye solo porque el propio Glasser et al. 2016 la agrupa junto a 6ma/6mp, sin evidencia propia verificada de participacion en circuitos procedimentales de extremidades.', NULL, now()),
